    HTTP header names are case-insensitive, so fall back to a case-insensitive
    lookup when the canonical spelling is absent. Conflicting spellings carrying
    different values are treated as a malformed request instead of guessing.
    """

    if SIGNATURE_HEADER in headers:
        return True, headers[SIGNATURE_HEADER]

    candidates = [
        value
        for key, value in headers.items()
        if isinstance(key, str) and key.lower() == SIGNATURE_HEADER.lower()
    ]
    if not candidates:
        return False, None
    if any(candidate != candidates[0] for candidate in candidates[1:]):
        return False, None
    return True, candidates[0]


