    """Constant-time HMAC-SHA256 check of the untrusted request body."""

    found, header = _signature_header(headers)
    if not found:
        return False
    try:
        return bool(verify_signature(body, header, secret))
    except (TypeError, ValueError, UnicodeError):
        # Hostile header values (e.g. non-ASCII) are simply not valid.
        return False


