    """Decode a verified body into a payment event, or ``None`` if unusable."""

    try:
        event = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        return None
    if not isinstance(event, dict):
        return None
    if any(not isinstance(event.get(field), str) for field in REQUIRED_EVENT_FIELDS):
        return None
    if not event["event_id"]:
        return None
    return event


