{"content":""""Contract tests for the Linkweave webhook receiver.

These complement ``tests/test_webhooks.py``: they pin down the documented
behaviour of ``handle_webhook`` (signature first, single append, no queueing of
rejected deliveries) without modifying the supplied test module.
"""
from __future__ import annotations

import json
import os
import tempfile
import unittest
from unittest import mock

import event_store
import webhooks
from signature_utils import signature_for
from webhooks import handle_webhook


VALID_EVENT = {
    "event_id": "evt-contract-001",
    "event_type": "invoice.paid",
    "account_id": "acct-001",
}


class ReceiverTestCase(unittest.TestCase):
    def setUp(self):
        self.secret = "contract-test-secret"
        self.log = tempfile.NamedTemporaryFile(delete=False)
        self.log.close()
        os.environ["WEBHOOK_SECRET"] = self.secret
        os.environ["WEBHOOK_EVENTS"] = self.log.name

    def tearDown(self):
        os.unlink(self.log.name)
        os.environ.pop("WEBHOOK_SECRET", None)
        os.environ.pop("WEBHOOK_EVENTS", None)

    def request(self, body, signature=None, secret=None, header=webhooks.SIGNATURE_HEADER):
        if signature is None and body is not None and secret is not False:
            signature = signature_for(body, self.secret if secret is None else secret)
        headers = {} if signature is False else {header: signature}
        return {"headers": headers, "body": body}

    def signed(self, event=VALID_EVENT, **kwargs):
        return self.request(json.dumps(event, sort_keys=True).encode("utf-8"), **kwargs)

    def queued(self):
        with open(self.log.name, encoding="utf-8") as handle:
            return [json.loads(line) for line in handle if line.strip()]


class AcceptedEventTests(ReceiverTestCase):
    def test_accepted_response_matches_documented_shape(self):
        self.assertEqual(
            handle_webhook(self.signed()),
            {"status": "accepted", "event_id": "evt-contract-001"},
        )

    def test_event_is_queued_exactly_once(self):
        handle_webhook(self.signed())
        self.assertEqual(self.queued(), [VALID_EVENT])

    def test_extra_fields_are_preserved(self):
        event = dict(VALID_EVENT, amount=1250, currency="EUR")
        response = handle_webhook(self.signed(event))
        self.assertEqual(response["event_id"], event["event_id"])
        self.assertEqual(self.queued(), [event])

    def test_lowercase_signature_header_is_accepted(self):
        response = handle_webhook(self.signed(header="x-webhook-signature"))
        self.assertEqual(response["status"], "accepted")
        self.assertEqual(len(self.queued()), 1)

    def test_queue_helper_is_used(self):
        with mock.patch.object(event_store, "append_event") as append:
            self.assertEqual(handle_webhook(self.signed())["status"], "accepted")
        append.assert_called_once_with(VALID_EVENT)

    def test_module_level_helper_override_is_used(self):
        with mock.patch.object(webhooks, "append_event") as append:
            self.assertEqual(handle_webhook(self.signed())["status"], "accepted")
        append.assert_called_once_with(VALID_EVENT)
        self.assertEqual(self.queued(), [])


class RejectedRequestTests(ReceiverTestCase):
    def assert_rejected(self, request):
        response = handle_webhook(request)
        self.assertEqual(response.get("status"), "rejected", response)
        self.assertNotIn("event_id", response)
        self.assertEqual(self.queued(), [])
        return response

    def test_missing_signature(self):
        self.assert_rejected(self.request(json.dumps(VALID_EVENT).encode(), signature=False))

    def test_tampered_body(self):
        body = json.dumps(VALID_EVENT).encode("utf-8")
        request = self.request(body)
        request["body"] = json.dumps(dict(VALID_EVENT, account_id="acct-999")).encode("utf-8")
        self.assert_rejected(request)

    def test_signature_from_another_secret(self):
        self.assert_rejected(self.signed(secret="attacker-secret"))

    def test_signature_without_algorithm_prefix(self):
        body = json.dumps(VALID_EVENT).encode("utf-8")
        raw = signature_for(body, self.secret).removeprefix("sha256=")
        self.assert_rejected(self.request(body, signature=raw))

    def test_non_string_signature(self):
        body = json.dumps(VALID_EVENT).encode("utf-8")
        self.assert_rejected(self.request(body, signature=12345))
        self.assert_rejected(self.request(body, signature=["sha256=deadbeef"]))

    def test_non_ascii_signature_does_not_raise(self):
        body = json.dumps(VALID_EVENT).encode("utf-8")
        self.assert_rejected(self.request(body, signature="sha256=\u00e9" * 4))

    def test_conflicting_signature_headers(self):
        request = self.signed()
        request["headers"]["x-webhook-signature"] = "sha256=" + "0" * 64
        self.assert_rejected(request)

    def test_malformed_json(self):
        self.assert_rejected(self.request(b"{not json"))
        self.assert_rejected(self.request(b""))

    def test_non_utf8_body(self):
        self.assert_rejected(self.request(b'{"event_id": "\xff\xfe"}'))

    def test_json_that_is_not_an_object(self):
        for payload in (b"[1, 2, 3]", b'"evt-1"', b"42", b"true", b"null"):
            with self.subTest(payload=payload):
                self.assert_rejected(self.request(payload))

    def test_missing_or_wrong_typed_required_fields(self):
        payloads = (
            {"event_type": "invoice.paid", "account_id": "acct-001"},
            {"event_id": "evt-1", "account_id": "acct-001"},
            {"event_id": "evt-1", "event_type": "invoice.paid"},
            {"event_id": 7, "event_type": "invoice.paid", "account_id": "acct-001"},
            {"event_id": "evt-1", "event_type": None, "account_id": "acct-001"},
            {"event_id": "", "event_type": "invoice.paid", "account_id": "acct-001"},
        )
        for payload in payloads:
            with self.subTest(payload=payload):
                self.assert_rejected(self.request(json.dumps(payload).encode("utf-8")))

    def test_malformed_request_shapes(self):
        body = json.dumps(VALID_EVENT).encode("utf-8")
        signature = signature_for(body, self.secret)
        shapes = (
            {},
            {"body": body},
            {"headers": {"X-Webhook-Signature": signature}},
            {"headers": "nope", "body": body},
            {"headers": {"X-Webhook-Signature": signature}, "body": body.decode()},
            {"headers": {"X-Webhook-Signature": signature}, "body": None},
            {"headers": None, "body": body},
        )
        for request in shapes:
            with self.subTest(request=request):
                self.assert_rejected(request)

    def test_non_mapping_request(self):
        self.assert_rejected([("headers", {}), ("body", b"{}")])

    def test_missing_secret_rejects_even_well_signed_delivery(self):
        body = json.dumps(VALID_EVENT).encode("utf-8")
        os.environ["WEBHOOK_SECRET"] = ""
        self.assert_rejected(self.request(body, signature=signature_for(body, "")))


class OrderingTests(ReceiverTestCase):
    def test_body_is_not_parsed_before_verification(self):
        with mock.patch.object(webhooks.json, "loads", wraps=json.loads) as loads:
            handle_webhook(self.request(b"{", signature="sha256=" + "0" * 64))
        loads.assert_not_called()
        with mock.patch.object(webhooks.json, "loads", wraps=json.loads) as loads:
            handle_webhook(self.signed())
        loads.assert_called_once()

    def test_rejections_never_touch_the_event_store(self):
        with mock.patch.object(event_store, "append_event") as append:
            handle_webhook(self.request(b"not-json"))
            handle_webhook(self.request(b"{}", signature=False))
        append.assert_not_called()

    def test_no_secret_material_in_responses(self):
        for response in (handle_webhook(self.signed()), handle_webhook(self.request(b"{"))):
            self.assertNotIn(self.secret, json.dumps(response))


if __name__ == "__main__":
    unittest.main()
